ALTER TABLE BANK_NOTIFICATIONS ADD COLUMN LOAN_ID BIGINT REFERENCES BANK_LOANS(ID);
ALTER TABLE BANK_NOTIFICATIONS ADD CONSTRAINT BANK_NOTICE_KIND CHECK (KIND IN ('ACCOUNT_APPROVED','ACCOUNT_REJECTED','LOAN_APPROVED','LOAN_REJECTED'));
ALTER TABLE BANK_NOTIFICATIONS ADD CONSTRAINT BANK_NOTICE_REASON CHECK ((KIND IN ('ACCOUNT_REJECTED','LOAN_REJECTED') AND REASON IS NOT NULL) OR (KIND IN ('ACCOUNT_APPROVED','LOAN_APPROVED') AND REASON IS NULL));
ALTER TABLE BANK_NOTIFICATIONS ADD CONSTRAINT BANK_NOTICE_SUBJECT CHECK ((KIND IN ('ACCOUNT_APPROVED','ACCOUNT_REJECTED') AND LOAN_ID IS NULL) OR (KIND IN ('LOAN_APPROVED','LOAN_REJECTED') AND LOAN_ID IS NOT NULL));
CREATE UNIQUE INDEX BANK_NOTICE_EVENT ON BANK_NOTIFICATIONS(ACCOUNT_ID, KIND, LOAN_ID);
CREATE INDEX BANK_NOTICE_UNREAD ON BANK_NOTIFICATIONS(USER_ID, READ_AT);
